// --- inputs -----------------------------------------------------------------
let inboundEmail = actions.get_incoming_email_addresses_int.records[0];
let htmlBody = ZT.getVariableValue("HtmlBody", "");
let subject = ZT.getVariableValue("sf_Subject", "");

// Zingtree drops merge results into the send Connected Object's JSON template as-is, with no
// escaping. Any value with quotes, backslashes or line breaks (an HTML body always has them)
// makes the rendered body invalid JSON, and Zingtree then sends the whole body as an escaped
// string -> Salesforce JSON_PARSER_ERROR at line 1 column 3. So every free-text value is
// escaped here for the position it sits in.
const jsonText = (value) => JSON.stringify(value == null ? "" : String(value)).slice(1, -1);

// --- CC list ------------------------------------------------------------------
// EmailMessage.CcAddress separates addresses with semicolons. The template reads this BARE:
//   "ccAddresses": ${transforms.ccAddresses}
// A real array merged as nothing when empty ("ccAddresses": ,), so it is staged as JSON
// text: "[]" when there is no CC, ["a@x.com","b@y.com"] otherwise.
let ccAddresses = [];
if (inboundEmail.CcAddress) {
  let addresses = inboundEmail.CcAddress.split(";");
  for (let i = 0; i < addresses.length; i++) {
    let address = addresses[i].trim();
    if (address !== "") {
      ccAddresses.push(address);
    }
  }
}

// --- outputs --------------------------------------------------------------------
// Template reads: "emailSubject": "${transforms.email_subject_json}",
//                 "emailBody": "${transforms.email_body_json}"
// HtmlBody and sf_Subject themselves stay untouched.
ZT.setTransformData("ccAddresses", JSON.stringify(ccAddresses));
ZT.setTransformData("email_body_json", jsonText(htmlBody));
ZT.setTransformData("email_subject_json", jsonText(subject));

