// Test mode only. Seeds Connected Object responses so the AI Actions run against the edited
// test email. How much is seeded is the QA choice on screen 44:
//   mock_all_requests     - all four responses seeded, routers 3/31/34/37 skip every Data
//                           node, nothing reaches Salesforce. The default, and the only
//                           workable setting in the sandbox org 605565.
//   mock_case_fetch_only  - only the case fetch is seeded, the way the UK source of truth
//                           does it; the account lookup, the CC lookup and the send run live
//                           against the Case Id and Account Id typed on screen 44. UK org 123
//                           only, and the send at node 38 is a real email.
// mock_downstream carries that choice to the routers. Nothing here runs on the live path.

// --- inputs -----------------------------------------------------------------
let test_subject = ZT.getVariableValue("test_subject", "Testing Case");
let test_email = ZT.getVariableValue("test_email", "");
let example_body = ZT.getVariableValue("test_example_body", "");
let test_intent = ZT.getVariableValue("test_intent", "test_fast_admin_active_card_list");
let test_mock_scope = ZT.getVariableValue("test_mock_scope", "mock_all_requests");
// Only read when the scope is mock_case_fetch_only; the defaults are the UK source of truth's
// own test case, so a QA run that leaves them blank still points at a real record.
let test_sf_case_id = ZT.getVariableValue("test_sf_case_id", "");
let test_sf_account_id = ZT.getVariableValue("test_sf_account_id", "");
let mock_all = test_mock_scope !== "mock_case_fetch_only";
let caseId = "500Ad00000MOCK0001";
let accountId = "001Ad00000MOCK0001";
if (!mock_all) {
  caseId = test_sf_case_id.trim() !== "" ? test_sf_case_id.trim() : "500Ad00000dG5JwIAK";
  accountId = test_sf_account_id.trim() !== "" ? test_sf_account_id.trim() : "001Ad000010Va2fIAC";
}
let emailBody = test_email.trim() !== "" ? test_email : example_body;
// Salesforce stores the inbound email as HTML in Case.Description.
let description = emailBody.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\n/g, "<br>");

// --- the journey under test -----------------------------------------------------
// The scenario key carries it: test_hc_ scenarios mock a Homecharge case, everything else a
// FAST Admin one. Node 8 then resolves queue_route from the mocked queue exactly as it
// does on a live case, so the routing decision is under test too.
let route = test_intent.indexOf("test_hc_") === 0 ? "homecharge" : "fast_admin";
const mockCaseByRoute = {
  fast_admin: {
    queue: "FAST_Admin", caseNumber: "02716246",
    suppliedEmail: "test.customer@example.co.uk",
    toAddress: "customerservices@allstarcard.co.uk",
    ccAddress: "fleet.admin@example.co.uk; accounts@example.co.uk",
    accountAdmin: "SME Unmanaged", contactId: "003Ad00000MOCK0001"
  },
  homecharge: {
    queue: "Allstar_Chargepass", caseNumber: "02716247",
    suppliedEmail: "test.driver@example.co.uk",
    toAddress: "homecharge@allstarcard.co.uk",
    ccAddress: null,
    // Only the fleet scenario mocks a linked Contact - that is what the driver / fleet
    // default on screen 21 reads.
    accountAdmin: "AS HC1", contactId: test_intent === "test_hc_fleet_requester" ? "003Ad00000MOCK0001" : null
  }
};
let mockCase = mockCaseByRoute[route];

// --- outputs: the same form data a real launch would carry ---------------------
ZT.setFormData("is_mock_run", true);
// The routers read this one, not is_mock_run: a case-fetch-only run is still a mock run, but
// its Data nodes must execute.
ZT.setFormData("mock_downstream", mock_all);
ZT.setFormData("sf_Id", caseId);
ZT.setFormData("caseId", caseId);
ZT.setFormData("sf_CaseNumber", mockCase.caseNumber);
ZT.setFormData("sf_Subject", test_subject);

// --- outputs: mocked Connected Object responses ---------------------------------
ZT.setResponseData("sfdc_int__case_email_ai", {
  _zt_meta: { response: { code: 200 } },
  totalSize: 1, done: true,
  records: [{
    Id: caseId, CaseNumber: mockCase.caseNumber, Subject: test_subject, Description: description,
    SuppliedEmail: mockCase.suppliedEmail, AccountId: accountId, ContactId: mockCase.contactId,
    Origin: "Email", Status: "New", Topic__c: "Please select one", Sub_Topic__c: "Please select one",
    Business_Process__c: "Operations", RecordTypeId: "0124J000000Cv1rQAA", OwnerId: "00G4J000000jcvjUAA",
    Initial_Case_Queue_Name__c: mockCase.queue, Last_Owner_Queue_Name__c: mockCase.queue, Queue_Email__c: null,
    CreatedDate: "2026-09-11T09:15:32.000+0000", Last_Email_Date__c: "2026-09-11T09:15:18.000+0000"
  }]
});
// The three downstream responses are seeded only when the whole run is mocked. Under
// mock_case_fetch_only the routers fall through to nodes 5, 35 and 38 and these are answered
// live by Salesforce.
if (mock_all) {
  ZT.setResponseData("get_account_details__int", {
    _zt_meta: { response: { code: 200 } },
    totalSize: 1, done: true,
    records: [{ Id: accountId, Name: "Northgate Plumbing Ltd", Framework__c: null,
      Account_Segment__c: "SME", AS_Account_Administrator__c: mockCase.accountAdmin }]
  });
  ZT.setResponseData("get_incoming_email_addresses_int", {
    _zt_meta: { response: { code: 200 } },
    totalSize: 1, done: true,
    records: [{ Id: "02sAd00000MOCK0001", FromAddress: mockCase.suppliedEmail, ToAddress: mockCase.toAddress,
      CcAddress: mockCase.ccAddress, BccAddress: null, Incoming: true, MessageDate: "2026-09-11T09:15:18.000+0000" }]
  });
  ZT.setResponseData("send_email_simple_int", {
    _zt_meta: { response: { code: 200 } },
    value: [{ actionName: "emailSimple", isSuccess: true, errors: [], outputValues: {} }]
  });
}

