// --- the two Salesforce restricted picklists, verbatim --------------------------
// Both fields are restricted picklists: a value that does not match Salesforce
// character for character is rejected on save. Two entries read as typos -
// "SSE Airticity" and "Uknown / Unspecified" - and are kept exactly as Salesforce
// holds them. Declared here only; screen 51's selects are the only reader.
const energyProviders = [
  "100 Green",
  "British Gas",
  "Budget Energy",
  "Click Energy",
  "Co Op Energy",
  "E Energy",
  "E.ON Next",
  "Ecotricity",
  "EDF",
  "Electric Ireland",
  "Energia",
  "Fuse Energy",
  "Home Energy",
  "Octopus Energy",
  "Outfox The Market",
  "OVO",
  "Power NI",
  "Sainsbury's Energy",
  "Scottish Gas",
  "Scottish Power",
  "Shell Energy",
  "So Energy",
  "SSE",
  "SSE Airticity",
  "Unknown / Unspecified",
  "Utilita",
  "Utility Warehouse"
];

const dataProviders = [
