  "Project EV",
  "Rolec",
  "Shell Recharge",
  "Uknown / Unspecified",
  "VCHARGD",
  "Zaptec"
];

// --- transform: the two dynamic-select sources ----------------------------------
// A native dynamic list source can only read a transform, and the option objects
// carry label and value under the names screen 51's config maps.
const toOptions = (values) => {
  let options = [];
  for (let i = 0; i < values.length; i++) {
    options.push({ value: values[i], label: values[i] });
  }
  return options;
};

ZT.setTransformData("energy_provider_options", toOptions(energyProviders));
ZT.setTransformData("data_provider_options", toOptions(dataProviders));

// --- transform: the guidance above the native fields ----------------------------
let provider_fields_html = "<div class=\"zt-content-block\">"
  + "<h3>Confirm the provider details</h3>"
  + "<p>These two fields write back to the case with the reply. Both lists are the"
  + " Salesforce picklists - pick Unknown / Unspecified rather than guessing.</p>"
  + "</div>";

ZT.setTransformData("provider_fields_html", provider_fields_html);
